@startuml

class Cinema {
  + town : string
}

class Theatre {
  + capacity : int
}

class Movie {
  + title : string
}

class MovieCopy {
}

class Show {
  + startTime : datetime
  + isPublished : boolean
}

class Reservation {
  + reservationTime : datetime
}

class Seat {
  + seatNumber : string
}

class Ticket {
  + seatNumber : string
}

class CreditCard {
  + cardNumber : string
}

class Offer {
  + expiryTime : datetime
}

Cinema "1" *-- "*" Theatre
Cinema "1" *-- "*" MovieCopy
Theatre "1" -- "*" Show
Movie "1" -- "*" MovieCopy
MovieCopy "1" -- "*" Show
Show "1" -- "*" Reservation
Show "1" -- "*" Ticket
Show "1" -- "0..1" Offer
Reservation "*" -- "1" Seat
Reservation "1" -- "1" CreditCard
Reservation "1" -- "1" Customer
Ticket "1" -- "1" Seat
Ticket "1" -- "1" Show

class Customer {
  + name : string
}

@enduml

